mapper.select:
select id, sensor_id, smoke_concentration, temperature, battery_level, device_status, collection_time, create_time, update_time, remark
from sensor_data_log


        and sensor_id = #{sensorId}


        and smoke_concentration = #{smokeConcentration}


        and temperature = #{temperature}


        and battery_level = #{batteryLevel}


        and device_status = #{deviceStatus}


        and collection_time = #{collectionTime}


        and date_format(collection_time,'%y%m%d') >= date_format(#{beginTime},'%y%m%d')


        and date_format(collection_time,'%y%m%d') <= date_format(#{endTime},'%y%m%d')


order by collection_time desc
